import pandas as pd,numpy as np,json,math
d=pd.read_csv(\"respondents.csv\"); w=d.wt_final; allm=pd.Series(True,index=d.index)
def base(m,e=allm):
 v=w[m];return dict(eligible_n=int(e.sum()),eligible_w=round(w[e].sum(),3),valid_n=int(m.sum()),valid_w=round(v.sum(),3),ess=round(v.sum()**2/(v*v).sum(),2))
def stat(c,codes,e=allm):
 m=e&d[c].isin(codes);r=base(m,e);r[\"pct\"]={str(k):round(100*w[m&d[c].eq(k)].sum()/w[m].sum(),3) for k in codes};r[\"missing\"]={str(k):{\"n\":int((e&d[c].eq(k)).sum()),\"w\":round(w[e&d[c].eq(k)].sum(),3)} for k in [97,98,99] if (e&d[c].eq(k)).any()};return r
out={}
for c in [c for c in d if c.startswith(\"att_\")]+[\"tool_satisfaction_5\"]:
 out[c]=stat(c,range(1,6),d.planning_tool_28d.isin([1,2,3]) if c==\"tool_satisfaction_5\" else allm)
for c in [\"need_budget\",\"need_effort\",\"need_waste\",\"over_budget_4w\",\"planning_tool_28d\",\"shared_list_use_28d\"]:
 out[c]=stat(c,range(4) if c==\"planning_tool_28d\" else [0,1],d.planning_tool_28d.isin([1,2,3]) if c==\"shared_list_use_28d\" else allm)
for prefix,status in [(\"support_\",\"needs_block_status\"),(\"barrier_\",\"barriers_block_status\")]:
 m=d[status].eq(1);cs=[c for c in d if c.startswith(prefix)];r=base(m);r[\"pct\"]={c:round(100*np.average(d.loc[m,c],weights=w[m]),3) for c in cs};r[\"none_pct\"]=round(100*w[m&d[cs].eq(0).all(axis=1)].sum()/w[m].sum(),3);r[\"missing\"]=stat(status,[1])[\"missing\"];out[status]=r
spec=[(\"NEED_EFFORT_TOPUPS\",\"need_effort\",\"unplanned_topups_7d\"),(\"NEED_EFFORT_PLANNING\",\"need_effort\",\"meal_plan_days_7d\"),(\"NEED_BUDGET_OVERSPEND\",\"need_budget\",\"over_budget_4w\"),(\"NEED_WASTE_DISCARD\",\"need_waste\",\"waste_days_7d\"),(\"CHILDREN_TOPUPS\",\"children_u16\",\"unplanned_topups_7d\"),(\"CHILDREN_PLANNING\",\"children_u16\",\"meal_plan_days_7d\")]
tests=[]
for aid,g,y in spec:
 valid=d[g].isin([0,1])&d[y].isin([0,1] if y==\"over_budget_4w\" else range(8));a=np.zeros(len(d));r={\"id\":aid}
 for k in [1,0]:
  e=d[g].eq(k);m=e&valid;mu=np.average(d.loc[m,y],weights=w[m]);a[m]=(1 if k else -1)*w[m]*(d.loc[m,y]-mu)/w[m].sum();r[str(k)]={**base(m,e),\"mean\":mu,\"outcome_nonvalid\":{str(z):int((e&d[y].eq(z)).sum()) for z in [97,98]}}
 diff=r[\"1\"][\"mean\"]-r[\"0\"][\"mean\"];var=0
 for ix in d.groupby([\"age_band\",\"children_u16\"]).indices.values():
  ah=a[ix];var+=len(ix)/(len(ix)-1)*((ah-ah.mean())**2).sum()
 se=math.sqrt(var);r.update(diff=diff,se=se,ci=[diff-1.959963984540054*se,diff+1.959963984540054*se],p=math.erfc(abs(diff/se)/math.sqrt(2)))
 if y==\"over_budget_4w\":
  for k in [\"1\",\"0\"]:r[k][\"mean\"]*=100
  for k in [\"diff\",\"se\"]:r[k]*=100
  r[\"ci\"]=[v*100 for v in r[\"ci\"]]
 tests.append(r)
for inds in [list(range(4)),[4,5]]:
 order=sorted(inds,key=lambda i:tests[i][\"p\"]);prev=0
 for j,i in enumerate(order):
  prev=max(prev,min(1,(len(inds)-j)*tests[i][\"p\"]));tests[i][\"p_holm\"]=prev
out[\"tests\"]=tests
cs=[\"need_budget\",\"need_effort\",\"need_waste\"];m=d[cs].isin([0,1]).all(axis=1);r=base(m);r[\"combinations\"]={}
for vals in [(a,b,c) for a in [0,1] for b in [0,1] for c in [0,1]]:
 z=m&(d[cs]==vals).all(axis=1);r[\"combinations\"][\"\".join(map(str,vals))]=round(100*w[z].sum()/w[m].sum(),3)
out[\"overlap\"]=r
m=d.att_plan_ahead_5.between(1,5)&d.att_spontaneous_5.between(1,5)&d.meal_plan_days_7d.between(0,7)
x=(d.loc[m,\"att_plan_ahead_5\"]+6-d.loc[m,\"att_spontaneous_5\"])/2;y=d.loc[m,\"meal_plan_days_7d\"];wm=w[m];xm=np.average(x,weights=wm);ym=np.average(y,weights=wm)
out[\"orientation\"]={**base(m),\"r\":np.average((x-xm)*(y-ym),weights=wm)/math.sqrt(np.average((x-xm)**2,weights=wm)*np.average((y-ym)**2,weights=wm))}
out[\"validation\"]={\"n\":len(d),\"w\":w.sum(),\"ess\":w.sum()**2/(w*w).sum(),\"unique_ids\":d.respondent_id.nunique(),\"derived_mismatches\":{},\"unasked_nonusers\":int(d.planning_tool_28d.eq(0).sum()),\"unasked_unknown\":int(d.planning_tool_28d.isin([97,98]).sum())}
for state,cs in [(\"need_budget\",[\"att_budget_worry_5\",\"att_price_tradeoffs_5\"]),(\"need_effort\",[\"att_time_short_5\",\"att_decision_fatigue_5\"]),(\"need_waste\",[\"att_waste_concern_5\",\"att_waste_difficult_5\"])]:
 expected=np.where(d[cs].isin(range(1,6)).all(axis=1),d[cs].ge(4).all(axis=1).astype(int),99);out[\"validation\"][\"derived_mismatches\"][state]=int((d[state]"'!=expected).sum())
print(json.dumps(out))
'"'"

